using AdDatabase.API.DTOs;using AdDatabase.API.Extensions;using AdDatabase.API.Hubs;using AdDatabase.BLL.Entities;using AdDatabase.BLL.Interfaces;using AdDatabase.BLL.Models;using AutoMapper;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.SignalR;
namespace AdDatabase.API.Controllers;[Authorize,ApiController,Route("api/conversations")]public class ConversationsController(IConversationService service,IMapper mapper,IHubContext<ChatHub> hub):ControllerBase{[HttpGet("my")]public async Task<IActionResult>Mine(CancellationToken ct)=>Ok(ApiResponse<List<Conversation>>.Ok(await service.MineAsync(User.UserId(),ct)));[HttpGet("{id:int}/messages")]public async Task<IActionResult>Messages(int id,CancellationToken ct)=>Ok(ApiResponse<Conversation>.Ok(await service.MessagesAsync(User.UserId(),id,ct)));[HttpPost("{id:int}/messages")]public async Task<IActionResult>Send(int id,SendMessageDto d,CancellationToken ct){var m=await service.SendAsync(User.UserId(),id,mapper.Map<SendMessageRequest>(d),ct);await hub.Clients.Group($"conversation:{id}").SendAsync("MessageReceived",m,ct);return Ok(ApiResponse<Message>.Ok(m,"Message sent"));}}
